import { BarChart } from '@dreadnought/ui/react';
const categories = [{id:'one',label:'One'},{id:'two',label:'Two'}];
const series = [{id:'a',label:'A',values:{one:20,two:-10}}];
export function Example() { return <BarChart label="Баланс" categories={categories} series={series} domain={[-20,40]} width={500} height={300} />; }

import { BarChart, useBarChart } from '@dreadnought/ui/react';
const categories=[{id:'one',label:'One'}]; const series=[{id:'a',label:'A',values:{one:10}}];
function Summary() { const {visible}= useBarChart(); return <p>Видимых серий: {visible.length}</p>; }
export function Example() { return <BarChart label="Данные" categories={categories} series={series} domain={[0,20]}><Summary /><BarChart.Legend>{({defaultContent}) => <span>{defaultContent}</span>}</BarChart.Legend><BarChart.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</BarChart.Plot><BarChart.Table /><BarChart.Pagination /><BarChart.Empty /></BarChart>; }
